        if n < 20:
            if opp_defects <= max(1, n // 10):
                return 'C'
            return 'D'

        if opp_rate > 0.35:
            return 'D'

        if opp_rate > 0.15:
            recent5_opp_def = 0
            start = n - 5 if n >= 5 else 0
            for i in range(start, n):
