def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my = [h[0] for h in history]
    op = [h[1] for h in history]
    op_c = op.count('C')
    op_d = n - op_c
    my_c = my.count('C')
    my_d = n - my_c
    last = op[-1]
    my_last = my[-1]
    rounds_left = 100 - n

    # Opponent's defection streak
    d_streak = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'D':
            d_streak += 1
        else:
            break

    # Opponent's cooperation streak
    c_streak = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'C':
            c_streak += 1
        else:
            break

    # Always-defect detection
    if op_c == 0:
        return 'D'

    # Always-cooperate detection: exploit patiently, then heavily at the end
    if op_d == 0:
        if rounds_left <= 3:
            return 'D'
        # Probe every so often to catch naive cooperators, but mostly stay friendly
        if n >= 4 and n % 11 == 0:
            return 'D'
        return 'C'

    # Near-always-defect: punish
    if n >= 6 and op_d >= n - 1:
        return 'D'

    # Near-always-cooperate: build trust then exploit at the end
    if n >= 6 and op_c >= n - 1:
        if rounds_left <= 4:
            return 'D'
        if n % 9 == 0 and rounds_left > 6:
            return 'D'
        return 'C'

    # Detect tit-for-tat: opponent mimics our previous move
    if n >= 8:
        mimic = 0
        for i in range(1, n):
            if op[i] == my[i - 1]:
                mimic += 1
        if mimic >= (n - 1) * 9 // 10:
            # TFT: cooperate to keep mutual C, defect only at the very end
            if rounds_left <= 1:
                return 'D'
            # Occasional jab can be profitable against forgiving TFT
            if rounds_left > 10 and n % 14 == 0:
                return 'D'
            return 'C'

    # Detect grim trigger: they defected after our first defection and stayed that way
    if n >= 5 and my_d > 0:
        first_d = -1
        for i in range(n):
            if my[i] == 'D':
                first_d = i
                break
        if first_d >= 0:
            after = op[first_d + 1:]
            if after and all(a == 'D' for a in after):
                return 'D'

    # Close-to-end exploitation based on opponent cooperation rate
    if rounds_left <= 2:
        if op_c * 2 >= n:
            return 'D'
        if d_streak >= 2:
            return 'D'
        return 'C' if op_c * 3 >= n * 2 else 'D'

    if rounds_left <= 6:
        if op_c * 3 >= n * 2:
            return 'D'
        if d_streak >= 1:
            return 'D'
        return 'C' if op_c * 5 >= n * 3 else 'D'

    if rounds_left <= 12:
        if op_c * 4 >= n * 3:
            return 'D' if op_c * 3 >= n * 2 else 'C'
        if d_streak >= 2:
            return 'D'
        return 'C'

    # General play: Tit-for-Tat with forgiveness and anti-exploitation
    if last == 'C':
        # Reward cooperation; occasionally probe cooperators late
        if c_streak >= 4 and rounds_left < 40 and rng.random() < 0.06:
            return 'D'
        return 'C'

    # Opponent defected
    if d_streak >= 3:
        # Persistent defection - retaliate hard
        return 'D'

    if d_streak == 2:
        # Two in a row; punish unless opponent looks recoverable
        if op_c * 3 >= n * 2:
            # Mostly cooperative with a hiccup; forgive sparingly
            return 'C' if rng.random() < 0.25 else 'D'
        return 'D'

    # Single defection: retaliate once, then forgive if they return to C
    if my_last == 'D':
        # We already punished last round; try to restore cooperation
        return 'C'
    return 'D'
