import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Aggregate counts in one pass
    opp_c = 0
    opp_d = 0
    me_d = 0
    for me, op in history:
        if op == 'C':
            opp_c += 1
        else:
            opp_d += 1
        if me == 'D':
            me_d += 1

    # Pure always-cooperator: exploit moderately on a fixed cadence, but
    # keep the relationship alive so we don't trigger retaliation.
    if opp_d == 0:
        if n >= 96:
            return 'D'
        # Exploit roughly every 6th round but not near the opening.
        if n >= 8 and n % 6 == 0:
            return 'D'
        return 'C'

    # Pure always-defector: never forgive, just defect.
    if opp_c == 0:
        return 'D'

    last_me, last_op = history[-1]

    # Recent window analysis (last 8 rounds)
    start = n - 8 if n >= 8 else 0
    recent_opp_d = 0
    recent_opp_c = 0
    for i in range(start, n):
        if history[i][1] == 'C':
            recent_opp_c += 1
        else:
            recent_opp_d += 1
    recent_len = n - start

    defect_rate = opp_d / n

    # Endgame: extract final value from a cooperative partner.
    if n >= 90:
        if defect_rate < 0.35:
            # Defect in the last few rounds against a cooperator.
            if n >= 96:
                return 'D'
            # Alternate: defect twice, cooperate once to keep them guessing low.
            if n % 3 != 0:
                return 'D'
            return 'C'
        if n >= 94:
            return 'D'

    # If opponent is very cooperative lately, cooperate (CC=3 is the best long run).
    if recent_opp_d == 0:
        # Rare probe to test if we can exploit, but not so often we get punished.
        if recent_len >= 6 and n % 7 == 3 and defect_rate < 0.2:
            return 'D'
        return 'C'

    # Opponent defected a lot recently -> sustained defection.
    if recent_opp_d >= recent_len - 1 and recent_len >= 4:
        return 'D'

    # Opponent mostly defecting overall -> defect to secure DD=1 over CD=0.
    if defect_rate > 0.5:
        # Occasional cooperative probe to escape mutual-defection traps.
        if rng.random() < 0.06:
            return 'C'
        return 'D'

    # If opponent just defected: retaliate, but with a calibrated forgiveness
    # based on their long-term and recent record.
    if last_op == 'D':
        # Very low defection rate overall: forgive quickly to preserve CC.
        if defect_rate <= 0.15:
            if rng.random() < 0.65:
                return 'C'
            return 'D'
        # Moderate defection: retaliate strongly but forgive sometimes.
        if recent_opp_d >= 3:
            return 'D'
        if rng.random() < 0.35:
            return 'C'
        return 'D'

    # Opponent just cooperated.
    if last_me == 'D':
        # We probed; return to cooperation against non-chronic defectors.
        if defect_rate > 0.45 and rng.random() < 0.4:
            return 'D'
        return 'C'

    # Default: cooperate, occasionally probe against semi-cooperative types.
    if defect_rate < 0.3 and recent_opp_c >= 3:
        if n % 9 == 0 and my_defects_small(me_d, opp_d):
            return 'D'
        return 'C'

    # Mid-range: solid reciprocal behavior.
    return 'C'


def my_defects_small(me_d, opp_d):
    return me_d <= opp_d

