                return 'C'
            if rng.random() < 0.7:
                return 'C'
            return 'D'
        # Mid-game cooperative state
        if defect_rate < 0.3:
            return 'C'
        # Mixed opponent: cooperate but watch
        if rng.random() < 0.88:
            return 'C'
        return 'D'

    return 'C'

