            elif a == 'C' and b == 'D':
                cd += 1
            elif a == 'D' and b == 'C':
                dc += 1
            else:
                dd += 1
        # If we often defected into cooperation, that's profitable; continue.
        if dc >= 2 and cc >= 1:
            if rng.random() < 0.45:
                return 'D'
        # If mutual defection dominates, try to break out.
        if dd >= 3 and cc == 0:
            if rng.random() < 0.6:
                return 'C'

    # Tit-for-tat style with small probabilistic forgiveness.
    if opp[-1] == 'D':
        if rng.random() < 0.12:
            return 'C'
        return 'D'
    return 'C'
