        return 'D'

    recent = history[-12:]
    r_opp_c = sum(1 for a, b in recent if b == 'C')
    r_len = len(recent)
    r_opp_d = r_len - r_opp_c

    if r_opp_d >= r_len - 1:
        return 'D'
    if r_opp_c >= r_len - 1:
        if n >= 30 and rng.random() < 0.06:
            return 'D'
