    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            run_opp_D += 1
        else:
            break
    run_opp_C = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            run_opp_C += 1
        else:
            break

