    n = len(history)
    if n == 0:
        return 'C'

    # Count overall rates
    opp_c = 0
    my_c = 0
    for (me, opp) in history:
        if opp == 'C':
            opp_c += 1
        if me == 'C':
            my_c += 1
    opp_d = n - opp_c
    opp_rate = opp_c / n

    last_me, last_opp = history[-1]

    # Detect opponent defection streak
    opp_streak_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_streak_d += 1
        else:
            break

    # Detect our own defection streak
    my_streak_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D':
            my_streak_d += 1
        else:
            break

    # Recent window analysis
    w = 10 if n >= 10 else n
    recent_opp_c = 0
    for i in range(n - w, n):
        if history[i][1] == 'C':
            recent_opp_c += 1

    # Early: cooperate, but retaliate immediately
    if n < 4:
        if last_opp == 'D':
            return 'D'
        return 'C'

