import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    my_last, opp_last = history[-1]
    if n == 2:
        return 'D' if opp_last == 'D' else 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    total_opp_def = opp.count('D')
    total_opp_c = n - total_opp_def
    my_def = me.count('D')

    if total_opp_def == 0:
        if n >= 96:
            return 'D'
        if n >= 60 and n % 11 == 0:
            return 'D'
        return 'C'
    if total_opp_def == n:
        return 'D'

    recent = opp[-10:] if n >= 10 else opp
    rlen = len(recent)
    r_opp_c = recent.count('C')
    r_opp_d = rlen - r_opp_c

    if n >= 3 and opp[-3:].count('D') == 3:
        return 'D'

    if r_opp_d >= 7:
        return 'D'

    if r_opp_c >= 9:
        if n >= 92:
            return 'D'
        if n >= 25 and total_opp_c >= int(0.92 * n) and rng.random() < 0.20:
            return 'D'
        return 'C'

    opp_after_my_C = 0
    opp_after_my_C_D = 0
    opp_after_my_D = 0
    opp_after_my_D_D = 0
    start = 0
    if n > 60:
        start = n - 60
    for i in range(start, n - 1):
        if me[i] == 'C':
            opp_after_my_C += 1
            if opp[i + 1] == 'D':
                opp_after_my_C_D += 1
        else:
            opp_after_my_D += 1
            if opp[i + 1] == 'D':
                opp_after_my_D_D += 1
    p_d_after_c = opp_after_my_C_D / opp_after_my_C if opp_after_my_C > 0 else 0.0
    p_d_after_d = opp_after_my_D_D / opp_after_my_D if opp_after_my_D > 0 else 0.0

    if opp_after_my_D >= 4 and p_d_after_d > p_d_after_c - 0.05 and opp_after_my_D_D >= 3:
        if p_d_after_d >= 0.75 and p_d_after_d > p_d_after_c + 0.3:
            return 'D'
        if p_d_after_c > p_d_after_d + 0.35 and n > 25:
            return 'D'

    if n >= 90:
        if total_opp_c > total_opp_def:
            return 'D'
        return 'D' if opp_last == 'D' else 'C'

    if last_opp == 'D':
        if r_opp_d >= 3:
            return 'D'
        if n >= 4 and opp[-2] == 'D':
            return 'D'
        opp_rate = total_opp_def / n
        if opp_rate < 0.15 and my_def <= 2:
            return 'C'
        if rng.random() < 0.25:
            return 'D'
        return 'C'

    if n > 12 and total_opp_c >= int(0.85 * n):
        if n % 23 == 0:
            return 'D'
        if rng.random() < 0.05:
            return 'D'
    return 'C'

