def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    my = [h[0] for h in history]
    op = [h[1] for h in history]

    opp_def = 0
    my_def = 0
    for a in op:
        if a == 'D':
            opp_def += 1
    for a in my:
        if a == 'D':
            my_def += 1

    last_op = op[-1]
    last_my = my[-1]

    # Always defect if opponent has shown persistent defection recently
    recent_window = op[-6:] if n >= 6 else op
    recent_def = 0
    for a in recent_window:
        if a == 'D':
            recent_def += 1

    if recent_def >= 4:
        return 'D'

    # If opponent never defected, cooperate but probe late
    if opp_def == 0:
        if n >= 92 and rng.random() < 0.15:
            return 'D'
        return 'C'

    # Strongly retaliate against immediate defection
    if last_op == 'D':
        # If they defected after we cooperated, punish
        if last_my == 'C':
            return 'D'
        # If streak is long, keep defecting
        if recent_def >= 2:
            return 'D'
        # Otherwise punish with high probability, occasionally forgive to reset
        return 'D' if rng.random() < 0.85 else 'C'

    # Opponent cooperated last round
    # Compute opponent cooperation ratio
    opp_coop = n - opp_def

    # If opponent mostly cooperative, cooperate, with rare probing
    if opp_def * 4 <= n:
        # Late-game exploitation of pure cooperators
        if opp_def == 0 and n >= 95:
            return 'D' if rng.random() < 0.5 else 'C'
        if n >= 85 and opp_def * 10 <= n and rng.random() < 0.12:
            return 'D'
        return 'C'

    # Moderate defection rate: use tit-for-tat-like with cautious probing
    if opp_def * 2 <= n:
        if n >= 12 and rng.random() < 0.1:
            return 'D'
        return 'C'

    # High defection rate: defect more often to avoid being exploited
    if recent_def >= 2:
        return 'D'
    return 'D' if rng.random() < 0.5 else 'C'

