        if remaining <= 3:
            return 'D'
        # occasional probe
        if n % 7 == 0 and remaining > 5:
            return 'D'
        return 'C'

    # --- Always-defector detection ---
    if opp_c <= 1 and n >= 4:
        return 'D'

