            return 'D'
        if rng.random() < 0.12:
            return 'C'
        return 'D'

    # Opponent just defected after cooperating: retaliate, but be willing to forgive.
    if last_op == 'D':
        if total_op_d * 3 > n:
            return 'D'
        if recent_d >= 5:
            return 'D'
